/** Apply the canonical Care Score v1 formula at the data boundary. */
export function withComputedCareScore<T extends Company>(company: T): T {
  return { ...company, carefolio_score: breakdown(company).computed }
}

export const COMPANIES: Company[] = COMPANY_INPUTS.map(withComputedCareScore)

// ── Companies with confirmed public Greenhouse / Lever job boards ─────────────
// These are the companies we actively fetch jobs from.

const co = (id: string) => {
  const c = COMPANIES.find(c => c.id === id)
  if (!c) throw new Error(`Company not found: ${id}`)
  return c
}

